CREATE TABLE chatbot_pending_actions (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY, chatbot_profile_id BIGINT NOT NULL, type VARCHAR(30) NOT NULL, status VARCHAR(30) NOT NULL, message_id VARCHAR(255) NULL, payload_json LONGTEXT NULL, expires_at TIMESTAMP(6) NULL, created_at TIMESTAMP(6) NOT NULL, updated_at TIMESTAMP(6) NOT NULL, CONSTRAINT fk_action_profile FOREIGN KEY (chatbot_profile_id) REFERENCES chatbot_profiles(id), CONSTRAINT uk_action_message UNIQUE (message_id), INDEX idx_action_profile_status (chatbot_profile_id,status,created_at));
CREATE TABLE budget_alerts (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY, budget_id BIGINT NOT NULL, alert_type VARCHAR(20) NOT NULL, sent_at TIMESTAMP(6) NOT NULL, created_at TIMESTAMP(6) NOT NULL, updated_at TIMESTAMP(6) NOT NULL, CONSTRAINT fk_alert_budget FOREIGN KEY (budget_id) REFERENCES budgets(id) ON DELETE CASCADE, CONSTRAINT uk_budget_alert_type UNIQUE (budget_id,alert_type));
CREATE INDEX idx_chatbot_message_context ON chatbot_messages(chatbot_profile_id,created_at);
